from lib import *
S = SS('q26')
steps = [
    step("单个队列、单个消费者:100 条消息处理完成的顺序前 15 个是 0 到 14,相邻逆序对和总逆序对都是 0——同一个队列里消息本身是先进先出的,一个消费者按这个顺序处理就不会乱。", t=tl(S(1)), mark=lidx(S(1), '100 条,1 个消费者'), done=lidx(S(1), '100 条,1 个消费者'), kv=KV([['单队列', '先进先出'], ['单消费者', '按序处理'], ['逆序对', '0']], ['单消费者'])),
    step("多个消费者并发处理同一个队列(prefetch=1,200 条,每条处理耗时 10~50 ms 不等):消息仍然按顺序投递,但完成顺序乱了。1 个消费者 0 个逆序;2 个消费者相邻逆序 66、总逆序对 68,完成顺序前 12 个是 [0, 1, 2, 4, 5, 3, 7, 6, …];4 个消费者相邻逆序 113、总逆序对 298;8 个消费者相邻逆序 109、总逆序对 468。消费者越多,乱得越厉害。", t=tl(S(2)), mark=lidx(S(2), '4        ', '8        '), done=lidx(S(2), '1        ', '2        '), b=bars([['1 个消费者', 0, '0 逆序对'], ['2 个', 68, '68'], ['4 个', 298, '298'], ['8 个', 468, '468']], 468, mark=[2, 3], done=[0, 1]), kv=KV([['投递顺序', '按队列顺序'], ['完成顺序', '取决于各自处理时间'], ['消费者越多', '总逆序对越多']], ['完成顺序'])),
    step("另一个会打乱顺序的原因是 nack 并 requeue:每第 5 条(序号 % 10 == 5)先 nack(requeue)一次再处理。prefetch=1 的单个消费者上,被 requeue 的消息放回队首,马上又被取到,处理顺序仍是 0 到 29,没有被打乱;prefetch=10 时,处理顺序变成 …, 4, 6, 7, …, 14, 5, 16, …, 24, 15, 26, …, 29, 25——被 nack 的 5、15、25 排到了已经预取的后面才被处理。prefetch 越大,requeue 对顺序的破坏越大。", t=tl(S(3)), mark=lidx(S(3), 'prefetch=10 的处理顺序'), done=lidx(S(3), '处理顺序:', 'prefetch=1 的单个消费者'), kv=KV([['prefetch=1 + requeue', '放回队首,顺序不乱'], ['prefetch=10 + requeue', '5、15、25 被推迟到预取的消息之后'], ['原因', '已预取的消息先被处理']], ['prefetch=10 + requeue'])),
    step("要保序就要“同一类消息交给同一个消费者”:按 key 分区。8 个队列各 1 个消费者(4 个并发消费者各管 2 个队列),发布时用 crc32(账户) % 8 选队列。100 个账户、每个账户 10 条消息共 1000 条,全部处理完,每个账户内部顺序乱掉的有 0 个;不同账户之间仍然不保证顺序。100 个账户在 8 个队列里分布成 [12, 12, 12, 12, 12, 12, 14, 14]。代价是扩展性:并行度最多等于分区数,热点账户会让某个队列忙不过来。", t=tl(S(4)), mark=lidx(S(4), '顺序乱掉的有 0 个'), done=lidx(S(4), '处理了 1000 条', '分布'), b=bars([['普通共享队列(8 消费者)', 468, '总逆序对 468'], ['按 key 分区', 0, '0 个账户乱序']], 468, mark=[0], done=[1]), kv=KV([['保序的条件', '同 key → 同队列 → 同消费者'], ['不同 key', '不保证'], ['代价', '并行度 ≤ 分区数']], ['保序的条件'])),
]
A = mkartq('q26', 26, 'RabbitMQ,消息顺序,多消费者,requeue,按key分区,真实验证,动画演示',
    '在 RabbitMQ 4.3.6 上实测保序:单队列单消费者严格有序;多消费者并发会打乱完成顺序(2/4/8 个消费者总逆序对 68/298/468);prefetch=10 下被 nack 并 requeue 的消息会被推迟到已预取的之后;按 key 分区到 8 个队列后,100 个账户内部顺序 0 个乱序。',
    '消息在队列里是先进先出的,是不是就能保证“先发先处理”?多开几个消费者、碰上 nack 重试时,顺序会怎样?想要按账户保序又要并行,该怎么设计?这篇逐项量化。',
    [('68 → 468', '2 个与 8 个消费者并发处理同一队列时的总逆序对数'), ('5, 15, 25', 'prefetch=10 下被 nack 并 requeue 的三条消息,处理顺序被推迟到预取的消息之后'), ('0 / 100', '按 key 分区后,100 个账户里内部顺序乱掉的账户数')],
    [('队列内有序', '<p>同一个队列里,消息按发布顺序先进先出;一个消费者按序处理就是有序的。</p>'),
     ('多消费者', '<p>消息仍按顺序投递给不同消费者,但处理时间不同,完成顺序会乱。消费者越多越乱,实测 2 个消费者总逆序对 68,8 个 468。</p>'),
     ('requeue', '<p>prefetch=1 时被 requeue 的消息回到队首,顺序不变;prefetch 较大时,被 requeue 的消息会晚于已预取的消息被处理。</p>'),
     ('按 key 分区', '<p>要同时保序和并行,就按 key(如账户)哈希分到多个队列,每个队列一个消费者:同 key 有序,不同 key 不保证;并行度受分区数限制。</p>')],
    steps,
    [ENV_Q + '。消费者是线程里的 pika 连接,处理耗时用 time.sleep 模拟(基础 10 ms 的 1~5 倍,按序号确定性地变化);逆序对是对完成顺序统计;分区实验用 direct exchange + 8 个队列 + crc32 取模',
     '没有验证:单活跃消费者(x-single-active-consumer)保序;一致性哈希 exchange 插件分区;quorum / stream 队列上的同样现象;发布端多个并发发布者之间的顺序(这里只有一个发布者);消费者故障转移后的顺序;重试队列(死信回环)对顺序的破坏'],
    '消息顺序')
